// ========================================================
// @块ID PROTO-CORE-UTF8-001
// @名称 UTF-8 编解码模块
//
// @作用
// 提供纯逻辑实现的 UTF-8 编码与解码，不依赖 util.TextEncoder / @kit.ArkTS，
// 保证同一份代码既能在 HarmonyOS 运行，也能在 Node 单元测试中直接 import 验证。
//
// @输入
// UTF8编码：text 字符串
// UTF8解码：bytes 字节数组
//
// @输出
// UTF8编码：Uint8Array 字节序列
// UTF8解码：string 字符串
//
// @业务规则
// 代理对正确处理；解码遇到非法序列按 U+FFFD 处理并前进一字节，避免死循环。
//
// @副作用
// 无
// ========================================================

// ========================================================
// @块ID PROTO-CORE-UTF8-002
// @名称 UTF8编码
//
// @作用
// 将字符串编码为 UTF-8 字节数组，正确处理代理对（超过 U+FFFF 的码点）。
//
// @输入
// 文本: 待编码字符串
//
// @输出
// Uint8Array: UTF-8 字节序列
//
// @副作用
// 无
// ========================================================
export function UTF8编码(文本: string): Uint8Array {
  const 字节列表: number[] = [];
  for (let i = 0; i < 文本.length; i++) {
    let 码点: number = 文本.charCodeAt(i);
    // 代理对：高代理 + 低代理合成完整码点
    if (码点 >= 0xd800 && 码点 <= 0xdbff && i + 1 < 文本.length) {
      const 低代理: number = 文本.charCodeAt(i + 1);
      if (低代理 >= 0xdc00 && 低代理 <= 0xdfff) {
        码点 = 0x10000 + ((码点 - 0xd800) << 10) + (低代理 - 0xdc00);
        i++;
      }
    }
    if (码点 < 0x80) {
      字节列表.push(码点);
    } else if (码点 < 0x800) {
      字节列表.push(0xc0 | (码点 >> 6), 0x80 | (码点 & 0x3f));
    } else if (码点 < 0x10000) {
      字节列表.push(0xe0 | (码点 >> 12), 0x80 | ((码点 >> 6) & 0x3f), 0x80 | (码点 & 0x3f));
    } else {
      字节列表.push(
        0xf0 | (码点 >> 18),
        0x80 | ((码点 >> 12) & 0x3f),
        0x80 | ((码点 >> 6) & 0x3f),
        0x80 | (码点 & 0x3f)
      );
    }
  }
  return new Uint8Array(字节列表);
}

// ========================================================
// @块ID PROTO-CORE-UTF8-003
// @名称 UTF8解码
//
// @作用
// 将 UTF-8 字节数组解码为字符串，正确处理 1-4 字节序列与代理对回转。
//
// @输入
// 字节: UTF-8 字节序列
//
// @输出
// string: 解码后的字符串
//
// @业务规则
// 非法序列按 U+FFFD 处理并前进一字节，避免死循环。
// 大字符串按 8192 码点分块拼接，避免 fromCharCode 栈溢出。
//
// @副作用
// 无
// ========================================================
export function UTF8解码(字节: Uint8Array): string {
  const 码点列表: number[] = [];
  let i = 0;
  while (i < 字节.length) {
    const 首字节: number = 字节[i];
    if (首字节 < 0x80) {
      码点列表.push(首字节);
      i += 1;
    } else if ((首字节 & 0xe0) === 0xc0 && i + 1 < 字节.length) {
      码点列表.push(((首字节 & 0x1f) << 6) | (字节[i + 1] & 0x3f));
      i += 2;
    } else if ((首字节 & 0xf0) === 0xe0 && i + 2 < 字节.length) {
      码点列表.push(
        ((首字节 & 0x0f) << 12) | ((字节[i + 1] & 0x3f) << 6) | (字节[i + 2] & 0x3f)
      );
      i += 3;
    } else if ((首字节 & 0xf8) === 0xf0 && i + 3 < 字节.length) {
      const 码点: number =
        ((首字节 & 0x07) << 18) |
        ((字节[i + 1] & 0x3f) << 12) |
        ((字节[i + 2] & 0x3f) << 6) |
        (字节[i + 3] & 0x3f);
      // 转回 UTF-16 代理对
      码点列表.push(0xd800 + ((码点 - 0x10000) >> 10), 0xdc00 + ((码点 - 0x10000) & 0x3ff));
      i += 4;
    } else {
      // 非法序列：按 U+FFFD 处理并前进一个字节，避免死循环
      码点列表.push(0xfffd);
      i += 1;
    }
  }
  let 文本 = '';
  const 分块大小 = 8192;
  for (let 起点 = 0; 起点 < 码点列表.length; 起点 += 分块大小) {
    文本 += String.fromCharCode(...码点列表.slice(起点, 起点 + 分块大小));
  }
  return 文本;
}
